p(id="P11", titre="Le geste retour n'a pas d'aperçu, et cassera avec targetSdk 36",
  gravite=2, frequence=1, axes=["Familiarité", "Fonction"], effort="2 h", lot="L3",
  symptome="Le retour ferme la recherche puis l'écran du dessus (juste), mais sans l'aperçu de l'écran d'en dessous que montrent les apps de Google sur un Pixel. Avec targetSdk 36, Android n'appellera plus onBackPressed : le geste fermera l'app depuis une conversation.",
  preuves=[], mesures="build.gradle : targetSdk = 35 ; manifeste sans enableOnBackInvokedCallback. Android 16 : « onBackPressed is not called and KeyEvent.KEYCODE_BACK is not dispatched anymore » pour targetSdk 36.",
  cause="MainActivity.kt:158-165.", impact="Aujourd'hui : chaque retour, sans aperçu. Au passage à targetSdk 36 : chaque retour depuis un écran ouvert ferme l'app.",
  options=[("A. OnBackInvokedCallback (API 33, sans androidx)", ["Aperçu système", "Prêt pour 36"], ["Enregistrer / retirer le rappel selon la pile"], True), ("B. Rester sur onBackPressed", ["Rien à faire"], ["Cassé en 36"], False)],
  choix="A. Un rappel actif seulement quand la pile a plus d'un écran ou qu'une recherche est ouverte ; à l'accueil, aucun rappel : Android anime le retour à l'écran d'accueil.",
  refs=["aback", "a16"], tranche=None,
  spec=[("MainActivity.kt:158-165", "override fun onBackPressed() { … }", "private val back = OnBackInvokedCallback { if (stack.lastOrNull()?.back() != true) pop(); syncBack() }\nfun syncBack() { if (stack.size > 1 || stack.last().wantsBack) onBackInvokedDispatcher.registerOnBackInvokedCallback(PRIORITY_DEFAULT, back) else onBackInvokedDispatcher.unregisterOnBackInvokedCallback(back) }"),
        ("AndroidManifest.xml:26-29", "<application …>", "<application android:enableOnBackInvokedCallback=\"true\" …>")],
  criteres=["Test : avec targetSdk 36, depuis une conversation, le retour ramène à l'accueil.", "Sur le Pixel : glisser depuis le bord montre l'accueil derrière la conversation."], proto=None)

